-- WBS Templates -> Construction Work Library: link the template construction tasks to activities (2026-11-05).
--
-- Review (scratchpad wbs-template-activity-review-decided.xlsx): WBS templates give the location tree, the Work Library
-- defines each task; a template task links through its master_code (apply_wbs_template then sets
-- wbs_tasks.activity_master_id, so Generate / the BOQ programme reuse the task instead of adding a duplicate).
-- Rule agreed 2026-11-05: construction tasks (Construction phase and every floor block) link; Design, Procurement,
-- T&C / Handover, milestones and non-work disciplines stay free. Decisions by Claude at the user's request:
-- 543 distinct unlinked names -> 460 linked to an existing activity, 53 to 20 new DRAFT activities, 10 free,
-- 20 multi-trade summaries left unlinked to be split in the editor.
--   A. CSI sections the new activities need.
--   B. 20 draft activities (hierarchy, discipline and work type taken from a similar activity; no norm yet, so the
--      quantity-based ones show "No norm" until norms are added).
--   C. master_code on 779 template tasks, only where the task has none (existing links are never changed),
--      only when that activity exists in this database and the task key AND name match the reviewed task
--      (a template edited differently elsewhere is left as it is).
-- Additive: no template node or task is added or removed.

-- ── A. CSI sections ───────────────────────────────────────────────────────
on conflict (code) do nothing;

-- ── B. New draft activities ───────────────────────────────────────────────
    status, version, owner, source, effective_date, duration_basis, csi_division_code, csi_section_code, trade, activity_type)
select v.code, v.name, l.domain_id, l.category_id, l.family_id, l.discipline, l.work_type, v.unit,
       'draft', 1, 'Planning Standards', 'Company Standard (WBS template review 2026-11)', date '2026-11-05', v.basis,
       v.div, v.sec, coalesce(l.trade, v.trade), 'construction'
from (values
  ('WL-03-WSTOP-001', 'Waterstops, Cast-in Items & Embeds', 'm', 'quantity', '03', '03 15 00', 'Structure', 'D03-033'),
  ('WL-07-FLOODTEST-001', 'Flood / Water-tightness Test', 'lot', 'fixed', '07', '07 10 00', 'Architecture', 'D07-002'),
  ('WL-07-WPPROT-001', 'Waterproofing Protection (Screed / Board)', 'm²', 'quantity', '07', '07 10 00', 'Architecture', 'D07-006'),
  ('WL-03-BWIC-001', 'Builder''s Work for MEP (Openings, Sleeves, Penetrations)', 'lot', 'fixed', '03', '03 15 00', 'Structure', 'D03-033'),
  ('WL-31-PILEHEAD-001', 'Pile Head Breaking & Trimming', 'nos', 'quantity', '31', '31 63 00', 'Structure', 'D31-001'),
  ('WL-05-FALLARREST-001', 'Roof Fall-arrest Anchors & Lifelines', 'm', 'quantity', '05', '05 50 00', 'Structure', 'D05-014'),
  ('WL-01-TRAFFIC-001', 'Temporary Traffic Management & Diversion', 'lot', 'fixed', '01', '01 55 26', 'General', 'D01-015'),
  ('WL-01-ENVCTRL-001', 'Environmental Controls (Silt Fences / Curtains)', 'lot', 'fixed', '01', '01 57 13', 'General', 'D01-015'),
  ('WL-01-HAULROAD-001', 'Temporary Access & Haul Roads', 'm²', 'quantity', '01', '01 55 23', 'General', 'D01-017'),
  ('WL-31-MARINETW-001', 'Marine Temporary Works (Jetty, Trestle, Cofferdam)', 'lot', 'fixed', '31', '31 50 00', 'Civil', 'D31-015'),
  ('WL-31-DWALL-001', 'Diaphragm Wall / Secant Piles', 'm²', 'quantity', '31', '31 50 00', 'Structure', 'D31-015'),
  ('WL-11-WEIGHBRIDGE-001', 'Weighbridge Installation', 'nos', 'fixed', '11', '11 13 00', 'Civil', 'D11-001'),
  ('WL-13-COLDROOM-001', 'Cold Room Installation', 'm²', 'quantity', '13', '13 21 00', 'Architecture', 'D13-005'),
  ('WL-09-RAISEDFLOOR-001', 'Raised Access Floor', 'm²', 'quantity', '09', '09 69 00', 'Architecture', 'D09-008'),
  ('WL-25-INSTR-001', 'Instrumentation & SCADA (Field Instruments, RTU, Configuration)', 'point', 'quantity', '25', '25 00 00', 'MEP', 'D25-004'),
  ('WL-26-OBSTLIGHT-001', 'Aviation / Navigation Obstruction Lights', 'nos', 'fixed', '26', '26 56 00', 'MEP', 'D26-004'),
  ('WL-33-STP-001', 'Sewage / Wastewater Treatment Plant (Package)', 'lot', 'fixed', '33', '33 30 00', 'MEP', 'D22-013'),
  ('WL-31-MSEWALL-001', 'Reinforced Earth (MSE) Wall', 'm²', 'quantity', '31', '31 32 00', 'Civil', 'D31-009'),
  ('WL-32-IRRIGATION-001', 'Landscape Irrigation System', 'm²', 'quantity', '32', '32 84 00', 'External Works', 'D32-011'),
  ('WL-07-FIRESTOP-001', 'Firestopping & Spandrel Seals', 'm', 'quantity', '07', '07 84 00', 'Architecture', 'D07-009')
) v(code, name, unit, basis, div, sec, trade, like_visible)
join lateral (select * from public.plan_act_masters x where x.visible_code = v.like_visible and x.status not in ('superseded', 'archived')
               order by x.version desc limit 1) l on true
join public.csi_sections s on s.code = v.sec
on conflict (code, version) do nothing;

-- ── C. master_code on template tasks ──────────────────────────────────────
create temp table _wl_links (template_name text, area text, level_type text, task_key text, task_name text, master_code text) on commit drop;

delete from _wl_links l where not exists (select 1 from public.plan_act_masters m where m.code = l.master_code);

-- sections
update public.wbs_templates w
   set content = jsonb_set(w.content, '{sections,tasks}', (
         select coalesce(jsonb_agg(case when l.master_code is not null and coalesce(t->>'master_code', '') = ''
                                        then t || jsonb_build_object('master_code', l.master_code) else t end order by o), '[]'::jsonb)
           from jsonb_array_elements(w.content->'sections'->'tasks') with ordinality e(t, o)
           left join _wl_links l on l.template_name = w.template_name and l.area = 'section' and l.task_key = t->>'key' and l.task_name = t->>'task_name'))
 where exists (select 1 from _wl_links l where l.template_name = w.template_name and l.area = 'section');

-- floor blocks
update public.wbs_templates w
   set content = jsonb_set(w.content, '{floor_blocks}', (
         select jsonb_object_agg(fb.k, jsonb_set(fb.v, '{tasks}', (
                  select coalesce(jsonb_agg(case when l.master_code is not null and coalesce(t->>'master_code', '') = ''
                                                 then t || jsonb_build_object('master_code', l.master_code) else t end order by o), '[]'::jsonb)
                    from jsonb_array_elements(coalesce(fb.v->'tasks', '[]'::jsonb)) with ordinality e(t, o)
                    left join _wl_links l on l.template_name = w.template_name and l.area = 'floor_block' and l.level_type = fb.k and l.task_key = t->>'key' and l.task_name = t->>'task_name')))
           from jsonb_each(w.content->'floor_blocks') fb(k, v)))
 where jsonb_typeof(w.content->'floor_blocks') = 'object'
   and exists (select 1 from _wl_links l where l.template_name = w.template_name and l.area = 'floor_block');
